#include "postquantiquecoin/wallet/WalletTransactionBuilder.h"
#include "postquantiquecoin/crypto/PQCAddress.h"
namespace pqc { uint64_t WalletTransactionBuilder::EstimateFee(size_t b,uint64_t r){return b*r;} void WalletTransactionBuilder::AddChangeOutput(Transaction& tx,const std::string& a,uint64_t amt){ TxOutput o; o.address=a; o.amountAtoms=amt; auto d=PQCAddress::Decode(a); if(d.IsOk()) o.publicKeyHash=d.Value().publicKeyHash; tx.outputs.push_back(o);} Result<void> WalletTransactionBuilder::FinalizeTransaction(Transaction& tx){ auto v=tx.ValidateBasic(); if(v.IsErr()) return v; tx.txid=tx.ComputeTxId(); return Result<void>::Ok();} Result<void> WalletTransactionBuilder::CommitToMempool(Mempool& m,const Transaction& tx,const UTXOSet& u,uint64_t h,const ChainParams& p,PQCryptoProvider* c){ return m.AddTransaction(tx,u,h,p,c);} }
